  std::any
  parseDepositWithdrawFees(std::any response, std::any codes = std::any{},
                           std::any currencyIdKey = std::any{}) override {
    //
    //    {
    //        "1INCH": {
    //            "is_depositable": true,
    //            "is_withdrawal": true,
    //            "ticker": "1INCH",
    //            "name": "1inch",
    //            "providers": [],
    //            "withdraw": {
    //                "max_amount": "0",
    //                "min_amount": "21.5",
    //                "fixed": "17.5",
    //                "flex": null
    //            },
    //            "deposit": {
    //                "max_amount": "0",
    //                "min_amount": "19.5",
    //                "fixed": null,
    //                "flex": null
    //            }
    //        },
    //        "WBT (ERC20)": {
    //            "is_depositable": true,
    //            "is_withdrawal": true,
    //            "ticker": "WBT",
    //            "name": "WhiteBIT Token",
    //            "providers": [],
    //            "withdraw": { max_amount: "0", min_amount: "0.7", fixed:
    //            "0.253", flex: null }, "deposit": { max_amount: "0",
    //            min_amount: "0.35", fixed: null, flex: null }
    //        },
    //        "WBT (TRC20)": {
    //            "is_depositable": true,
    //            "is_withdrawal": true,
    //            "ticker": "WBT",
    //            "name": "WhiteBIT Token",
    //            "providers": [],
    //            "withdraw": { max_amount: "0", min_amount: "1.5", fixed:
    //            "0.075", flex: null }, "deposit": { max_amount: "0",
    //            min_amount: "0.75", fixed: null, flex: null }
    //        },
    //        ...
    //    }
    //
    std::any depositWithdrawFees = ccxt::dict{};
    codes = this->marketCodes(codes);
    std::any currencyIds = getObjectKeys(response);
    for (std::any i = 0; isLessThan(i, getArrayLength(currencyIds));
         postFixIncrement(i)) {
      std::any entry = ::getValue(currencyIds, i);
      std::any splitEntry = split(entry, std::string(" "));
      std::any currencyId = ::getValue(splitEntry, 0);
      std::any feeInfo = ::getValue(response, entry);
      std::any code = this->safeCurrencyCode(currencyId);
      if (isTrue(isTrue((!isEqual(code, std::any{}))) &&
                 isTrue((isTrue((isEqual(codes, std::any{}))) ||
                         isTrue((this->inArray(code, codes))))))) {
        std::any depositWithdrawFee =
            this->safeValue(depositWithdrawFees, code);
        if (isTrue(isEqual(depositWithdrawFee, std::any{}))) {
          ::setValue(depositWithdrawFees, code,
                     this->depositWithdrawFee(ccxt::dict{}));
        }
        ::setValue(::getValue(::getValue(depositWithdrawFees, code),
                              std::string("info")),
                   entry, feeInfo);
        std::any networkId = this->safeString(splitEntry, 1);
        std::any withdraw = this->safeValue(feeInfo, std::string("withdraw"));
        std::any deposit = this->safeValue(feeInfo, std::string("deposit"));
        std::any withdrawFee = this->safeNumber(withdraw, std::string("fixed"));
        std::any depositFee = this->safeNumber(deposit, std::string("fixed"));
        std::any withdrawResult = ccxt::dict{
            {std::string("fee"), withdrawFee},
            {std::string("percentage"),
             (isTrue((!isEqual(withdrawFee, std::any{})))
                  ? std::any(false)
                  : std::any(std::any{}))},
        };
        std::any depositResult = ccxt::dict{
            {std::string("fee"), depositFee},
            {std::string("percentage"),
             (isTrue((!isEqual(depositFee, std::any{})))
                  ? std::any(false)
                  : std::any(std::any{}))},
        };
        if (isTrue(!isEqual(networkId, std::any{}))) {
          std::any networkLength = getStringLength(networkId);
          networkId = slice(networkId, 1, subtract(networkLength, 1));
          std::any networkCode = this->networkIdToCode(networkId, code);
          if (isTrue(!isEqual(networkCode, std::any{}))) {
            ::setValue(::getValue(::getValue(depositWithdrawFees, code),
                                  std::string("networks")),
                       networkCode,
                       ccxt::dict{
                           {std::string("withdraw"), withdrawResult},
                           {std::string("deposit"), depositResult},
                       });
          }
        } else {
          ::setValue(::getValue(depositWithdrawFees, code),
                     std::string("withdraw"), withdrawResult);
          ::setValue(::getValue(depositWithdrawFees, code),
                     std::string("deposit"), depositResult);
        }
      }
    }
    std::any depositWithdrawCodes = getObjectKeys(depositWithdrawFees);
    for (std::any i = 0; isLessThan(i, getArrayLength(depositWithdrawCodes));
         postFixIncrement(i)) {
      std::any code = ::getValue(depositWithdrawCodes, i);
      std::any currency = this->currency(code);
      ::setValue(depositWithdrawFees, code,
                 this->assignDefaultDepositWithdrawFees(
                     ::getValue(depositWithdrawFees, code), currency));
    }
    return depositWithdrawFees;
  }

  /**
   * @method
   * @name whitebit#fetchTradingFees
   * @description fetch the trading fees for multiple markets
   * @see https://docs.whitebit.com/public/http-v4/#asset-status-list
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a dictionary of [fee structures]{@link
   * https://docs.ccxt.com/?id=fee-structure} indexed by market symbols
   */
  std::shared_future<std::any>
  fetchTradingFees(std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any response =
                     awaitValue(this->v4PublicGetAssets(params));
                 //
                 //      {
                 //          "1INCH": {
                 //              "name": "1inch",
                 //              "unified_cryptoasset_id": "8104",
                 //              "can_withdraw": true,
                 //              "can_deposit": true,
                 //              "min_withdraw": "33",
                 //              "max_withdraw": "0",
                 //              "maker_fee": "0.1",
                 //              "taker_fee": "0.1",
                 //              "min_deposit": "30",
                 //              "max_deposit": "0"
                 //            },
                 //            ...
                 //      }
                 //
                 std::any result = ccxt::dict{};
                 std::any symbols = this->symbols;
                 for (std::any i = 0; isLessThan(i, getArrayLength(symbols));
                      postFixIncrement(i)) {
                   std::any symbol = ::getValue(symbols, i);
                   std::any market = this->market(symbol);
                   std::any fee = this->safeValue(
                       response, ::getValue(market, std::string("baseId")),
                       ccxt::dict{});
                   std::any makerFee =
                       this->safeString(fee, std::string("maker_fee"));
                   std::any takerFee =
                       this->safeString(fee, std::string("taker_fee"));
                   makerFee =
                       ccxt::Precise::stringDiv(makerFee, std::string("100"));
                   takerFee =
                       ccxt::Precise::stringDiv(takerFee, std::string("100"));
                   ::setValue(
                       result, symbol,
                       ccxt::dict{
                           {std::string("info"), fee},
                           {std::string("symbol"),
                            ::getValue(market, std::string("symbol"))},
                           {std::string("percentage"), true},
                           {std::string("tierBased"), false},
                           {std::string("maker"), this->parseNumber(makerFee)},
                           {std::string("taker"), this->parseNumber(takerFee)},
                       });
                 }
                 return result;
               })
        .share();
  }

  /**
   * @method
   * @name whitebit#fetchTradingLimits
   * @description fetch the trading limits for a market
   * @see https://docs.whitebit.com/public/http-v4/#market-info
   * @param {string[]|undefined} symbols unified market symbol
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [trading limits structure]{@link
   * https://docs.ccxt.com/?id=trading-limits-structure}
   */
  std::shared_future<std::any>
  fetchTradingLimits(std::any symbols = std::any{},
                     std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 //
                 // Trading limits are derived from market information already
                 // loaded by loadMarkets() Market structure includes:
                 //     {
                 //         "id": "BTC_USDT",                    // Market ID
                 //         "symbol": "BTC/USDT",                // Unified
                 //         symbol "base": "BTC",                       // Base
                 //         currency "quote": "USDT",                     //
                 //         Quote currency "active": true, // Market active
                 //         status "type": "spot",                      //
                 //         Market type "spot": true,                        //
                 //         Spot trading enabled "margin": false, // Margin
                 //         trading enabled "future": false, // Futures trading
                 //         enabled "option": false,                     //
                 //         Options trading enabled "contract": false, //
                 //         Contract trading enabled "settle": undefined, //
                 //         Settlement currency "settleId": undefined, //
                 //         Settlement currency ID "contractSize": undefined, //
                 //         Contract size "linear": undefined, // Linear
                 //         contract "inverse": undefined,                //
                 //         Inverse contract "limits": { // Trading limits
                 //             "amount": {                      // Amount
                 //             limits
                 //                 "min": 0.00001,              // Minimum
                 //                 amount "max": 1000000               //
                 //                 Maximum amount
                 //             },
                 //             "price": {                       // Price limits
                 //                 "min": 0.01,                 // Minimum
                 //                 price "max": 1000000               //
                 //                 Maximum price
                 //             },
                 //             "cost": {                        // Cost limits
                 //                 "min": 5.0,                  // Minimum cost
                 //                 "max": 10000000              // Maximum cost
                 //             }
                 //         },
                 //         "precision": {                       // Precision
                 //         settings
                 //             "amount": 5,                     // Amount
                 //             precision "price": 2                       //
                 //             Price precision
                 //         },
                 //         "taker": 0.001,                      // Taker fee
                 //         "maker": 0.001,                      // Maker fee
                 //         "percentage": true,                  // Fee
                 //         percentage "tierBased": false                   //
                 //         Tier-based fees
                 //     }
                 //
                 std::any result = ccxt::dict{};
                 // Process all markets from the loaded markets cache
                 std::any markets = this->markets;
                 if (isTrue(isEqual(markets, std::any{}))) {
                   throw ExchangeError(toString(
                       add(this->id, std::string(" markets not loaded"))));
                 }
                 std::any marketIds = getObjectKeys(markets);
                 for (std::any i = 0; isLessThan(i, getArrayLength(marketIds));
                      postFixIncrement(i)) {
                   std::any marketId = ::getValue(marketIds, i);
                   std::any market = ::getValue(markets, marketId);
                   std::any marketSymbol =
                       this->safeString(market, std::string("symbol"));
                   if (isTrue(
                           isTrue(
                               isTrue(isTrue((isEqual(market, std::any{}))) ||
                                      isTrue((isEqual(market, null)))) ||
                               isTrue((isEqual(marketSymbol, std::any{})))) ||
                           isTrue((isEqual(marketSymbol, std::string("")))))) {
                     continue;
                   }
                   std::any symbol = ::getValue(market, std::string("symbol"));
                   // Filter by symbols if specified
                   if (isTrue(!isEqual(symbols, std::any{}))) {
                     std::any symbolFound = false;
                     for (std::any j = 0;
                          isLessThan(j, getArrayLength(symbols));
                          postFixIncrement(j)) {
                       if (isTrue(isEqual(::getValue(symbols, j), symbol))) {
                         symbolFound = true;
                         break;
                       }
                     }
                     if (!isTrue(symbolFound)) {
                       continue;
                     }
                   }
                   // Extract trading limits
                   std::any limits =
                       this->safeDict(market, std::string("limits"));
                   std::any amountLimits =
                       this->safeDict(limits, std::string("amount"));
                   std::any priceLimits =
                       this->safeDict(limits, std::string("price"));
                   std::any costLimits =
                       this->safeDict(limits, std::string("cost"));
                   // Validate that all required limits exist and are valid
                   // numbers
                   std::any hasAmountLimits =
                       isTrue(
                           isTrue(
                               isTrue((!isEqual(amountLimits, std::any{}))) &&
                               isTrue((!isEqual(amountLimits, null)))) &&
                           isTrue(!isEqual(this->safeNumber(amountLimits,
                                                            std::string("min")),
                                           std::any{}))) &&
                       isTrue(!isEqual(
                           this->safeNumber(amountLimits, std::string("max")),
                           std::any{}));
                   std::any hasPriceLimits =
                       isTrue(
                           isTrue(isTrue((!isEqual(priceLimits, std::any{}))) &&
                                  isTrue((!isEqual(priceLimits, null)))) &&
                           isTrue(!isEqual(this->safeNumber(priceLimits,
                                                            std::string("min")),
                                           std::any{}))) &&
                       isTrue(!isEqual(
                           this->safeNumber(priceLimits, std::string("max")),
                           std::any{}));
                   std::any hasCostLimits =
                       isTrue(
                           isTrue(isTrue((!isEqual(costLimits, std::any{}))) &&
                                  isTrue((!isEqual(costLimits, null)))) &&
                           isTrue(!isEqual(
                               this->safeNumber(costLimits, std::string("min")),
                               std::any{}))) &&
                       isTrue(!isEqual(
                           this->safeNumber(costLimits, std::string("max")),
                           std::any{}));
                   if (isTrue(isTrue(isTrue((isEqual(hasAmountLimits, true))) &&
                                     isTrue((isEqual(hasPriceLimits, true)))) &&
                              isTrue((isEqual(hasCostLimits, true))))) {
                     ::setValue(
                         result, symbol,
                         ccxt::dict{
                             {std::string("info"), market},
                             {std::string("limits"),
                              ccxt::dict{
                                  {std::string("amount"),
                                   ccxt::dict{
                                       {std::string("min"),
                                        this->safeNumber(amountLimits,
                                                         std::string("min"))},
                                       {std::string("max"),
                                        this->safeNumber(amountLimits,
                                                         std::string("max"))},
                                   }},
                                  {std::string("price"),
                                   ccxt::dict{
                                       {std::string("min"),
                                        this->safeNumber(priceLimits,
                                                         std::string("min"))},
                                       {std::string("max"),
                                        this->safeNumber(priceLimits,
                                                         std::string("max"))},
                                   }},
                                  {std::string("cost"),
                                   ccxt::dict{
                                       {std::string("min"),
                                        this->safeNumber(costLimits,
                                                         std::string("min"))},
                                       {std::string("max"),
                                        this->safeNumber(costLimits,
                                                         std::string("max"))},
                                   }},
                              }},
                         });
                   }
                 }
                 return result;
               })
        .share();
  }

  /**
   * @method
   * @name whitebit#fetchFundingLimits
   * @description fetch the deposit and withdrawal limits for a currency
   * @see https://docs.whitebit.com/public/http-v4/#asset-status-list
   * @see https://docs.whitebit.com/public/http-v4/#fee
   * @param {string[]|undefined} codes unified currency codes
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [funding limits structure]{@link
   * https://docs.ccxt.com/?id=funding-limits-structure}
   */
  virtual std::shared_future<std::any>
  fetchFundingLimits(std::any codes = std::any{},
                     std::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 // Fetch both currencies and fees data for comprehensive
                 // funding limits
                 std::any currenciesDatafeesDataVariable = awaitValue(
                     promiseAll(ccxt::list{this->fetchCurrencies(),
                                           this->v4PublicGetFee(params)}));
                 std::any currenciesData =
                     ::getValue(currenciesDatafeesDataVariable, 0);
                 std::any feesData =
                     ::getValue(currenciesDatafeesDataVariable, 1);
                 //
                 // Currencies response structure (from fetchCurrencies):
                 //     {
                 //         "BTC": {
                 //             "id": "BTC",                          //
                 //             Currency ID "code": "BTC", // Currency code
                 //             "name": "Bitcoin",                    //
                 //             Currency name "active": true, // Currency active
                 //             status "type": "crypto",                     //
                 //             Currency type "precision": 8, // Currency
                 //             precision "limits": { // Currency limits
                 //                 "deposit": {                      // Deposit
                 //                 limits
                 //                     "min": 0.00001,               // Minimum
                 //                     deposit "max": 1000000                //
                 //                     Maximum deposit
                 //                 },
                 //                 "withdraw": {                     //
                 //                 Withdrawal limits
                 //                     "min": 0.00001,               // Minimum
                 //                     withdrawal "max": 1000000 // Maximum
                 //                     withdrawal
                 //                 }
                 //             },
                 //             "networks": {                         //
                 //             Network-specific limits
                 //                 "BTC": {
                 //                     "limits": {
                 //                         "deposit": { "min": "0.001" },
                 //                         "withdraw": { "min": "0.002" }
                 //                     }
                 //                 }
                 //             },
                 //             "info": { ... }                       //
                 //             Original API response
                 //         }
                 //     }
                 //
                 // Fees response structure (from /api/v4/public/fee):
                 //     {
                 //         "USDT (ERC20)": {
                 //             "ticker": "USDT",
                 //             "name": "Tether US",
                 //             "deposit": {
                 //                 "min_amount": "0.0005",
                 //                 "max_amount": "0.1",
                 //                 "fixed": "0.0005",
                 //                 "flex": {
                 //                     "min_fee": "100",
                 //                     "max_fee": "1000",
                 //                     "percent": "10"
                 //                 }
                 //             },
                 //             "withdraw": {
                 //                 "min_amount": "0.001",
                 //                 "max_amount": "0",
                 //                 "fixed": null,
                 //                 "flex": null
                 //             }
                 //         }
                 //     }
                 //
                 std::any result = ccxt::dict{};
                 std::any currencyKeys = getObjectKeys(currenciesData);
                 for (std::any i = 0;
                      isLessThan(i, getArrayLength(currencyKeys));
                      postFixIncrement(i)) {
                   std::any code = ::getValue(currencyKeys, i);
                   std::any currency = ::getValue(currenciesData, code);
                   if (isTrue(isEqual(currency, std::any{}))) {
                     continue;
                   }
                   if (isTrue(isTrue(!isEqual(codes, std::any{})) &&
                              !isTrue(this->inArray(code, codes)))) {
                     continue;
                   }
                   // Find corresponding fee data for this currency
                   std::any feeData = std::any{};
                   std::any feeKeys = getObjectKeys(feesData);
                   for (std::any j = 0; isLessThan(j, getArrayLength(feeKeys));
                        postFixIncrement(j)) {
                     std::any feeKey = ::getValue(feeKeys, j);
                     std::any fee = this->safeDict(feesData, feeKey);
                     if (isTrue(isTrue((isTrue(!isEqual(fee, std::any{})) &&
                                        isTrue(!isEqual(fee, null)))) &&
                                isTrue(isEqual(
                                    ::getValue(fee, std::string("ticker")),
                                    code)))) {
                       feeData = fee;
                       break;
                     }
                   }
                   // Build comprehensive funding limits
                   std::any currencyLimits = this->safeDict(
                       currency, std::string("limits"), ccxt::dict{});
                   std::any limits = ccxt::dict{
                       {std::string("deposit"),
                        ccxt::dict{
                            {std::string("min"),
                             ::getValue(::getValue(currencyLimits,
                                                   std::string("deposit")),
                                        std::string("min"))},
                            {std::string("max"),
                             ::getValue(::getValue(currencyLimits,
                                                   std::string("deposit")),
                                        std::string("max"))},
                        }},
                       {std::string("withdraw"),
                        ccxt::dict{
                            {std::string("min"),
                             ::getValue(::getValue(currencyLimits,
                                                   std::string("withdraw")),
                                        std::string("min"))},
                            {std::string("max"),
                             ::getValue(::getValue(currencyLimits,
                                                   std::string("withdraw")),
                                        std::string("max"))},
                        }},
                   };
                   // Add fee information if available
                   if (isTrue(!isEqual(feeData, std::any{}))) {
                     std::any depositFee =
                         ::getValue(feeData, std::string("deposit"));
                     std::any withdrawFee =
                         ::getValue(feeData, std::string("withdraw"));
                     if (isTrue(isTrue((!isEqual(depositFee, std::any{}))) &&
                                isTrue((!isEqual(depositFee, null))))) {
                       std::any depositFeeData = ccxt::dict{
                           {std::string("fixed"),
                            this->safeNumber(depositFee, std::string("fixed"))},
                       };
                       if (isTrue(
                               isTrue((!isEqual(
                                   ::getValue(depositFee, std::string("flex")),
                                   std::any{}))) &&
                               isTrue((!isEqual(
                                   ::getValue(depositFee, std::string("flex")),
                                   null))))) {
                         ::setValue(depositFeeData, std::string("flex"),
                                    ccxt::dict{
                                        {std::string("min"),
                                         this->safeNumber(
                                             ::getValue(depositFee,
                                                        std::string("flex")),
                                             std::string("min_fee"))},
                                        {std::string("max"),
                                         this->safeNumber(
                                             ::getValue(depositFee,
                                                        std::string("flex")),
                                             std::string("max_fee"))},
                                        {std::string("percent"),
                                         this->safeNumber(
                                             ::getValue(depositFee,
                                                        std::string("flex")),
                                             std::string("percent"))},
                                    });
                       }
                       ::setValue(::getValue(limits, std::string("deposit")),
                                  std::string("fee"), depositFeeData);
                     }
                     if (isTrue(isTrue((!isEqual(withdrawFee, std::any{}))) &&
                                isTrue((!isEqual(withdrawFee, null))))) {
                       std::any withdrawFeeData = ccxt::dict{
                           {std::string("fixed"),
                            this->safeNumber(withdrawFee,
                                             std::string("fixed"))},
                       };
                       if (isTrue(
                               isTrue((!isEqual(
                                   ::getValue(withdrawFee, std::string("flex")),
                                   std::any{}))) &&
                               isTrue((!isEqual(
                                   ::getValue(withdrawFee, std::string("flex")),
                                   null))))) {
                         ::setValue(withdrawFeeData, std::string("flex"),
                                    ccxt::dict{
                                        {std::string("min"),
                                         this->safeNumber(
                                             ::getValue(withdrawFee,
                                                        std::string("flex")),
                                             std::string("min_fee"))},
                                        {std::string("max"),
                                         this->safeNumber(
                                             ::getValue(withdrawFee,
                                                        std::string("flex")),
                                             std::string("max_fee"))},
                                        {std::string("percent"),
                                         this->safeNumber(
                                             ::getValue(withdrawFee,
                                                        std::string("flex")),
                                             std::string("percent"))},
                                    });
                       }
                       ::setValue(::getValue(limits, std::string("withdraw")),
                                  std::string("fee"), withdrawFeeData);
                     }
                   }
                   // Add network-specific limits if available
                   if (isTrue(!isEqual(
                           ::getValue(currency, std::string("networks")),
                           std::any{}))) {
                     ::setValue(limits, std::string("networks"),
                                ::getValue(currency, std::string("networks")));
                   }
                   ::setValue(result, code,
                              ccxt::dict{
                                  {std::string("info"), currency},
                                  {std::string("limits"), limits},
                              });
                 }
                 return result;
               })
        .share();
  }

  /**
   * @method
   * @name whitebit#fetchTicker
   * @description fetches a price ticker, a statistical calculation with the
   * information calculated over the past 24 hours for a specific market
   * @see https://docs.whitebit.com/public/http-v4/#market-activity
   * @param {string} symbol unified symbol of the market to fetch the ticker for
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [ticker structure]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<std::any>
  fetchTicker(std::any symbol, std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any market = this->market(symbol);
                        std::any request = ccxt::dict{
                            {std::string("market"),
                             ::getValue(market, std::string("id"))},
                        };
                        std::any response = awaitValue(this->v1PublicGetTicker(
                            this->extend(request, params)));
                        //
                        //      {
                        //         "success":true,
                        //         "message":"",
                        //         "result": {
                        //             "bid":"0.021979",
                        //             "ask":"0.021996",
                        //             "open":"0.02182",
                        //             "high":"0.022039",
                        //             "low":"0.02161",
                        //             "last":"0.021987",
                        //             "volume":"2810.267",
                        //             "deal":"61.383565474",
                        //             "change":"0.76",
                        //         },
                        //     }
                        //
                        std::any ticker = this->safeDict(
                            response, std::string("result"), ccxt::dict{});
                        return this->parseTicker(ticker, market);
                      })
        .share();
  }

  std::any parseTicker(std::any ticker, std::any market = std::any{}) override {
    //
    //  FetchTicker (v1)
    //
    //    {
    //        "bid": "0.021979",
    //        "ask": "0.021996",
    //        "open": "0.02182",
    //        "high": "0.022039",
    //        "low": "0.02161",
    //        "last": "0.021987",
    //        "volume": "2810.267",
    //        "deal": "61.383565474",
    //        "change": "0.76",
    //    }
    //
    // FetchTickers (v4)
    //
    //    "BCH_RUB": {
    //        "base_id": 1831,
    //        "quote_id": 0,
    //        "last_price": "32830.21",
    //        "quote_volume": "1494659.8024096",
    //        "base_volume": "46.1083",
    //        "isFrozen": false,
    //        "change": "2.12" // in percent
    //    }
    //
    // WS market_update
    //
    //     {
    //         "open": "52853.04",
    //         "close": "55913.88",
    //         "high": "56272",
    //         "low": "49549.67",
    //         "volume": "57331.067185",
    //         "deal": "3063860382.42985338",
    //         "last": "55913.88",
    //         "period": 86400
    //     }
    // v2
    //   {
    //       lastUpdateTimestamp: '2025-01-02T09:16:36.000Z',
    //       tradingPairs: 'ARB_USDC',
    //       lastPrice: '0.7727',
    //       lowestAsk: '0.7735',
    //       highestBid: '0.7732',
    //       baseVolume24h: '1555793.74',
    //       quoteVolume24h: '1157602.622406',
    //       tradesEnabled: true
    //   }
    //
    // v4PublicGetFutures
    //     {
    //         "ticker_id": "0G_PERP",
    //         "stock_currency": "0G",
    //         "money_currency": "USDT",
    //         "last_price": "0.6065",
    //         "stock_volume": "2563218",
    //         "money_volume": "1587952.6137",
    //         "bid": "0.6065",
    //         "ask": "0.6077",
    //         "high": "0.6472",
    //         "low": "0.6045",
    //         "product_type": "Perpetual",
    //         "open_interest": "3721488",
    //         "index_price": "0.61",
    //         "index_name": "0G future contract",
    //         "index_currency": "0G",
    //         "funding_rate": "-0.00000778",
    //         "next_funding_rate_timestamp": "1772467200000",
    //         "brackets": {
    //             "1": 0,
    //             "10": 0,
    //             "100": 0,
    //             "2": 0,
    //             "20": 4000,
    //             "3": 0,
    //             "5": 0,
    //             "50": 800
    //         },
    //         "max_leverage": 50,
    //         "funding_interval_minutes": 240
    //     }
    //
    std::any marketId = this->safeString2(ticker, std::string("tradingPairs"),
                                          std::string("ticker_id"));
    market = this->safeMarket(marketId, market);
    // last price is provided as "last" or "last_price"
    std::any last = this->safeStringN(
        ticker, ccxt::list{std::string("last"), std::string("last_price"),
                           std::string("lastPrice")});
    // if "close" is provided, use it, otherwise use <last>
    std::any close = this->safeString(ticker, std::string("close"), last);
    return this->safeTicker(
        ccxt::dict{
            {std::string("symbol"), ::getValue(market, std::string("symbol"))},
            {std::string("timestamp"), std::any{}},
            {std::string("datetime"), std::any{}},
            {std::string("high"),
             this->safeString(ticker, std::string("high"))},
            {std::string("low"), this->safeString(ticker, std::string("low"))},
            {std::string("bid"), this->safeString2(ticker, std::string("bid"),
                                                   std::string("highestBid"))},
            {std::string("bidVolume"), std::any{}},
            {std::string("ask"), this->safeString2(ticker, std::string("ask"),
                                                   std::string("lowestAsk"))},
            {std::string("askVolume"), std::any{}},
            {std::string("vwap"), std::any{}},
            {std::string("open"),
             this->safeString(ticker, std::string("open"))},
            {std::string("close"), close},
            {std::string("last"), last},
            {std::string("previousClose"), std::any{}},
            {std::string("change"), std::any{}},
            {std::string("percentage"),
             this->safeString(ticker, std::string("change"))},
            {std::string("average"), std::any{}},
            {std::string("baseVolume"),
             this->safeStringN(ticker,
                               ccxt::list{std::string("base_volume"),
                                          std::string("volume"),
                                          std::string("baseVolume24h"),
                                          std::string("stock_volume")})},
            {std::string("quoteVolume"),
             this->safeStringN(ticker,
                               ccxt::list{std::string("quote_volume"),
                                          std::string("deal"),
                                          std::string("quoteVolume24h"),
                                          std::string("money_volume")})},
            {std::string("indexPrice"),
             this->safeString(ticker, std::string("index_price"))},
            {std::string("info"), ticker},
        },
        market);
  }

  /**
   * @method
   * @name whitebit#fetchOrder
   * @description fetches information on an order by the id
   * @see
   * https://docs.whitebit.com/private/http-trade-v4/#query-unexecutedactive-orders
   * @see https://docs.whitebit.com/private/http-trade-v4/#query-executed-orders
   * @param {string} id order id
   * @param {string} symbol unified symbol of the market the order was made in
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {boolean} [params.checkActive] whether to check active orders
   * (default: true)
   * @param {boolean} [params.checkExecuted] whether to check executed orders
   * (default: true)
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  fetchOrder(std::any id, std::any symbol = std::any{},
             std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 // Extract control parameters from params
                 std::any checkActive =
                     this->safeBool(params, std::string("checkActive"), true);
                 std::any checkExecuted =
                     this->safeBool(params, std::string("checkExecuted"), true);
                 params = this->omit(params,
                                     ccxt::list{std::string("checkActive"),
                                                std::string("checkExecuted")});
                 std::any request = ccxt::dict{
                     {std::string("orderId"), id},
                 };
                 std::any market = std::any{};
                 if (isTrue(!isEqual(symbol, std::any{}))) {
                   market = this->market(symbol);
                   ::setValue(request, std::string("market"),
                              ::getValue(market, std::string("id")));
                 }
                 // Try active orders first (if enabled)
                 if (isTrue(isEqual(checkActive, true))) {
                   try {
                     std::any response = awaitValue(this->v4PrivatePostOrders(
                         this->extend(request, params)));
                     // Search for order in active orders response (array
                     // format)
                     std::any orders = this->toArray(response);
                     for (std::any i = 0; isLessThan(i, getArrayLength(orders));
                          postFixIncrement(i)) {
                       std::any order = ::getValue(orders, i);
                       std::any orderId =
                           this->safeString(order, std::string("orderId"));
                       if (isTrue(isEqual(orderId, id))) {
                         std::any marketId =
                             this->safeString(order, std::string("market"));
                         std::any marketNew = this->safeMarket(
                             marketId, std::any{}, std::string("_"));
                         return this->parseOrder(order, marketNew);
                       }
                     }
                   } catch (const std::exception &error) {
                     if (!isTrue((isInstanceOf<OrderNotFound>(error)))) {
                       throw;
                     }
                   }
                 }
                 // Try executed orders (if enabled)
                 if (isTrue(isEqual(checkExecuted, true))) {
                   try {
                     std::any response =
                         awaitValue(this->v4PrivatePostTradeAccountOrderHistory(
                             this->extend(request, params)));
                     // Search for order in executed orders response (object
                     // format)
                     std::any marketIds = getObjectKeys(response);
                     for (std::any i = 0;
                          isLessThan(i, getArrayLength(marketIds));
                          postFixIncrement(i)) {
                       std::any marketId = ::getValue(marketIds, i);
                       std::any marketNew = this->safeMarket(
                           marketId, std::any{}, std::string("_"));
                       std::any marketOrders =
                           this->safeList(response, marketId, ccxt::list{});
                       for (std::any j = 0;
                            isLessThan(j, getArrayLength(marketOrders));
                            postFixIncrement(j)) {
                         std::any order = ::getValue(marketOrders, j);
                         std::any orderId =
                             this->safeString(order, std::string("id"));
                         if (isTrue(isEqual(orderId, id))) {
                           return this->parseOrder(order, marketNew);
                         }
                       }
                     }
                   } catch (const std::exception &error) {
                     if (!isTrue((isInstanceOf<OrderNotFound>(error)))) {
                       throw;
                     }
                   }
                 }
                 throw OrderNotFound(toString(
                     add(add(this->id,
                             std::string(" fetchOrder() order not found: ")),
                         id)));
                 return std::any{};
               })
        .share();
  }

  /**
   * @method
   * @name whitebit#fetchTickers
   * @description fetches price tickers for multiple markets, statistical
   * information calculated over the past 24 hours for each market
   * @see https://docs.whitebit.com/public/http-v4/#market-activity
   * @param {string[]} [symbols] unified symbols of the markets to fetch the
   * ticker for, all market tickers are returned if not assigned
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.type] 'spot' or 'swap' - default is 'spot'. If type
   * is 'swap', it will call v4PublicGetFutures
   * @param {string} [params.method] either v2PublicGetTicker or
   * v4PublicGetTicker or v4PublicGetFutures - default is v4PublicGetTicker for
   * spot and mixed markets, and v4PublicGetFutures for swap
   * @returns {object} a dictionary of [ticker structures]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<std::any>
  fetchTickers(std::any symbols = std::any{},
               std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 symbols = this->marketSymbols(symbols);
                 std::any onlyContractSymbols = true;
                 if (isTrue(!isEqual(symbols, std::any{}))) {
                   for (std::any i = 0; isLessThan(i, getArrayLength(symbols));
                        postFixIncrement(i)) {
                     std::any symbol = ::getValue(symbols, i);
                     std::any market = this->market(symbol);
                     if (isTrue(!isEqual(
                             ::getValue(market, std::string("contract")),
                             true))) {
                       onlyContractSymbols = false;
                       break;
                     }
                   }
                 } else {
                   onlyContractSymbols = false;
                 }
                 std::any marketType = std::any{};
                 std::any marketTypeparamsVariable =
                     this->handleMarketTypeAndParams(
                         std::string("fetchTickers"), std::any{}, params);
                 marketType = ::getValue(marketTypeparamsVariable, 0);
                 params = ::getValue(marketTypeparamsVariable, 1);
                 std::any method = std::any{};
                 std::any methodparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchTickers"), std::string("method"),
                     method);
                 method = ::getValue(methodparamsVariable, 0);
                 params = ::getValue(methodparamsVariable, 1);
                 if (isTrue(isEqual(method, std::any{}))) {
                   // if the user did not specify a method, choose it based on
                   // market type and symbols
                   if (isTrue(isTrue(onlyContractSymbols) ||
                              isTrue((
                                  isEqual(marketType, std::string("swap")))))) {
                     method = std::string("v4PublicGetFutures");
                   } else {
                     method = std::string("v4PublicGetTicker");
                   }
                 }
                 std::any response = std::any{};
                 if (isTrue(
                         isEqual(method, std::string("v4PublicGetTicker")))) {
                   //
                   //      "BCH_RUB": {
                   //          "base_id":1831,
                   //          "quote_id":0,
                   //          "last_price":"32830.21",
                   //          "quote_volume":"1494659.8024096",
                   //          "base_volume":"46.1083",
                   //          "isFrozen":false,
                   //          "change":"2.12"
                   //      },
                   //
                   response = awaitValue(this->v4PublicGetTicker(params));
                 } else if (isTrue(isEqual(
                                method, std::string("v4PublicGetFutures")))) {
                   //
                   //     {
                   //         "success": true,
                   //         "message": null,
                   //         "result": [
                   //             {
                   //                 "ticker_id": "0G_PERP",
                   //                 "stock_currency": "0G",
                   //                 "money_currency": "USDT",
                   //                 "last_price": "0.6065",
                   //                 "stock_volume": "2563218",
                   //                 "money_volume": "1587952.6137",
                   //                 "bid": "0.6065",
                   //                 "ask": "0.6077",
                   //                 "high": "0.6472",
                   //                 "low": "0.6045",
                   //                 "product_type": "Perpetual",
                   //                 "open_interest": "3721488",
                   //                 "index_price": "0.61",
                   //                 "index_name": "0G future contract",
                   //                 "index_currency": "0G",
                   //                 "funding_rate": "-0.00000778",
                   //                 "next_funding_rate_timestamp":
                   //                 "1772467200000", "brackets": {
                   //                     "1": 0,
                   //                     "10": 0,
                   //                     "100": 0,
                   //                     "2": 0,
                   //                     "20": 4000,
                   //                     "3": 0,
                   //                     "5": 0,
                   //                     "50": 800
                   //                 },
                   //                 "max_leverage": 50,
                   //                 "funding_interval_minutes": 240
                   //             }
                   //         ]
                   //     }
                   //
                   response = awaitValue(this->v4PublicGetFutures(params));
                 } else {
                   response = awaitValue(this->v2PublicGetTicker(params));
                 }
                 std::any resultList =
                     this->safeList(response, std::string("result"));
                 if (isTrue(!isEqual(resultList, std::any{}))) {
                   return this->parseTickers(resultList, symbols);
                 }
                 std::any marketIds = getObjectKeys(response);
                 std::any result = ccxt::dict{};
                 for (std::any i = 0; isLessThan(i, getArrayLength(marketIds));
                      postFixIncrement(i)) {
                   std::any marketId = ::getValue(marketIds, i);
                   std::any market = this->safeMarket(marketId);
                   std::any ticker = this->parseTicker(
                       ::getValue(response, marketId), market);
                   std::any symbol = ::getValue(ticker, std::string("symbol"));
                   ::setValue(result, symbol, ticker);
                 }
                 return this->filterByArrayTickers(
                     result, std::string("symbol"), symbols);
               })
        .share();
  }

  /**
   * @method
   * @name whitebit#fetchOrderBook
   * @description fetches information on open orders with bid (buy) and ask
   * (sell) prices, volumes and other data
   * @see https://docs.whitebit.com/public/http-v4/#orderbook
   * @param {string} symbol unified symbol of the market to fetch the order book
   * for
   * @param {int} [limit] the maximum amount of order book entries to return
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order book structure]{@link
   * https://docs.ccxt.com/?id=order-book-structure}
   */
  std::shared_future<std::any>
  fetchOrderBook(std::any symbol, std::any limit = std::any{},
                 std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{
                     {std::string("market"),
                      ::getValue(market, std::string("id"))},
                 };
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("limit"),
                              limit); // default = 100, maximum = 100
                 }
                 std::any response =
                     awaitValue(this->v4PublicGetOrderbookMarket(
                         this->extend(request, params)));
                 //
                 //      {
                 //          "timestamp": 1594391413,
                 //          "asks": [
                 //              [
                 //                  "9184.41",
                 //                  "0.773162"
                 //              ],
                 //              [ ... ]
                 //          ],
                 //          "bids": [
                 //              [
                 //                  "9181.19",
                 //                  "0.010873"
                 //              ],
                 //              [ ... ]
                 //          ]
                 //      }
                 //
                 std::any timestamp =
                     this->safeTimestamp(response, std::string("timestamp"));
                 return this->parseOrderBook(response, symbol, timestamp);
               })
        .share();
  }

  /**
   * @method
   * @name whitebit#fetchTrades
   * @description get the list of most recent trades for a particular symbol
   * @see https://docs.whitebit.com/public/http-v4/#recent-trades
   * @param {string} symbol unified symbol of the market to fetch trades for
   * @param {int} [since] timestamp in ms of the earliest trade to fetch
   * @param {int} [limit] the maximum amount of trades to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=public-trades}
   */
  std::shared_future<std::any>
  fetchTrades(std::any symbol, std::any since = std::any{},
              std::any limit = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{
                     {std::string("market"),
                      ::getValue(market, std::string("id"))},
                 };
                 std::any response = awaitValue(this->v4PublicGetTradesMarket(
                     this->extend(request, params)));
                 //
                 //      [
                 //          {
                 //              "tradeID": 158056419,
                 //              "price": "9186.13",
                 //              "quote_volume": "0.0021",
                 //              "base_volume": "9186.13",
                 //              "trade_timestamp": 1594391747,
                 //              "type": "sell"
                 //          },
                 //      ],
                 //
                 return this->parseTrades(response, market, since, limit);
               })
        .share();
  }

  /**
   * @method
   * @name whitebit#fetchMyTrades
   * @description fetch all trades made by the user
   * @see
   * https://docs.whitebit.com/private/http-trade-v4/#query-executed-order-history
   * @param {string} symbol unified symbol of the market to fetch trades for
   * @param {int} [since] timestamp in ms of the earliest trade to fetch
   * @param {int} [limit] the maximum amount of trades to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=public-trades}
   */
  std::shared_future<std::any>
  fetchMyTrades(std::any symbol = std::any{}, std::any since = std::any{},
                std::any limit = std::any{},
                std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = std::any{};
                 std::any request = ccxt::dict{};
                 if (isTrue(!isEqual(symbol, std::any{}))) {
                   market = this->market(symbol);
                   ::setValue(request, std::string("market"),
                              ::getValue(market, std::string("id")));
                 }
                 std::any response =
                     awaitValue(this->v4PrivatePostTradeAccountExecutedHistory(
                         this->extend(request, params)));
                 //
                 // when no symbol is provided
                 //
                 //   {
                 //       "USDC_USDT":[
                 //          {
                 //             "id":"1343815269",
                 //             "clientOrderId":"",
                 //             "time":"1641051917.532965",
                 //             "side":"sell",
                 //             "role":"2",
                 //             "amount":"9.986",
                 //             "price":"0.9995",
                 //             "deal":"9.981007",
                 //             "fee":"0.009981007",
                 //             "orderId":"58166729555"
                 //          },
                 //       ]
                 //   }
                 //
                 // when a symbol is provided
                 //
                 //     [
                 //         {
                 //             "id": 1343815269,
                 //             "clientOrderId": '',
                 //             "time": 1641051917.532965,
                 //             "side": "sell",
                 //             "role": 2,
                 //             "amount": "9.986",
                 //             "price": "0.9995",
                 //             "deal": "9.981007",
                 //             "fee": "0.009981007",
                 //             "orderId": 58166729555,
                 //         },
                 //     ]
                 //
                 if (isTrue(isArray(response))) {
                   return this->parseTrades(response, market, since, limit);
                 } else {
                   std::any results = ccxt::list{};
                   std::any keys = getObjectKeys(response);
                   for (std::any i = 0; isLessThan(i, getArrayLength(keys));
                        postFixIncrement(i)) {
                     std::any marketId = ::getValue(keys, i);
                     std::any marketNew = this->safeMarket(marketId, std::any{},
                                                           std::string("_"));
                     std::any rawTrades =
                         this->safeValue(response, marketId, ccxt::list{});
                     std::any parsed =
                         this->parseTrades(rawTrades, marketNew, since, limit);
                     results = this->arrayConcat(results, parsed);
                   }
                   results = this->sortBy2(results, std::string("timestamp"),
                                           std::string("id"));
                   return this->filterBySinceLimit(results, since, limit,
                                                   std::string("timestamp"));
                 }
                 return std::any{};
               })
        .share();
  }

  std::any parseTrade(std::any trade, std::any market = std::any{}) override {
    //
    // fetchTradesV4
    //
    //     {
    //       "tradeID": 158056419,
    //       "price": "9186.13",
    //       "quote_volume": "0.0021",
    //       "base_volume": "9186.13",
    //       "trade_timestamp": 1594391747,
    //       "type": "sell"
    //     }
    //
    // orderTrades (v4Private)
    //
    //     {
    //         "time": 1593342324.613711,
    //         "fee": "0.00000419198",
    //         "price": "0.00000701",
    //         "amount": "598",
    //         "id": 149156519, // trade id
    //         "dealOrderId": 3134995325, // orderId
    //         "clientOrderId": "customId11",
    //         "role": 2, // 1 = maker, 2 = taker
    //         "deal": "0.00419198" // amount in money
    //         "feeAsset": "USDT"
    //     }
    //
    // fetchMyTrades
    //
    //      {
    //          "id": 1343815269,
    //          "clientOrderId": '',
    //          "time": 1641051917.532965,
    //          "side": "sell",
    //          "role": 2,
    //          "amount": "9.986",
    //          "price": "0.9995",
    //          "deal": "9.981007",
    //          "fee": "0.009981007",
    //          "orderId": 58166729555,
    //          "feeAsset": "USDT"
    //      }
    //
    market = this->safeMarket(std::any{}, market);
    std::any timestamp = this->safeTimestamp2(trade, std::string("time"),
                                              std::string("trade_timestamp"));
    std::any orderId = this->safeString2(trade, std::string("dealOrderId"),
                                         std::string("orderId"));
    std::any cost = this->safeString(trade, std::string("deal"));
    std::any price = this->safeString(trade, std::string("price"));
    std::any amount = this->safeString2(trade, std::string("amount"),
                                        std::string("quote_volume"));
    std::any id =
        this->safeString2(trade, std::string("id"), std::string("tradeID"));
    std::any side =
        this->safeString2(trade, std::string("type"), std::string("side"));
    std::any symbol = ::getValue(market, std::string("symbol"));
    std::any role = this->safeInteger(trade, std::string("role"));
    std::any takerOrMaker = std::any{};
    if (isTrue(!isEqual(role, std::any{}))) {
      takerOrMaker =
          (isTrue((isEqual(role, 1))) ? std::any(std::string("maker"))
                                      : std::any(std::string("taker")));
    }
    std::any fee = std::any{};
    std::any feeCost = this->safeString(trade, std::string("fee"));
    if (isTrue(!isEqual(feeCost, std::any{}))) {
      fee = ccxt::dict{
          {std::string("cost"), feeCost},
          {std::string("currency"), this->safeCurrencyCode(this->safeString(
                                        trade, std::string("feeAsset")))},
      };
    }
    return this->safeTrade(
        ccxt::dict{
            {std::string("info"), trade},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("symbol"), symbol},
            {std::string("id"), id},
            {std::string("order"), orderId},
            {std::string("type"), std::any{}},
            {std::string("takerOrMaker"), takerOrMaker},
            {std::string("side"), side},
            {std::string("price"), price},
            {std::string("amount"), amount},
            {std::string("cost"), cost},
            {std::string("fee"), fee},
        },
        market);
  }

  /**
   * @method
   * @name whitebit#fetchOHLCV
   * @description fetches historical candlestick data containing the open, high,
   * low, and close price, and the volume of a market
   * @see https://docs.whitebit.com/public/http-v1/#kline
   * @param {string} symbol unified symbol of the market to fetch OHLCV data for
   * @param {string} timeframe the length of time each candle represents
   * @param {int} [since] timestamp in ms of the earliest candle to fetch
   * @param {int} [limit] the maximum amount of candles to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {int[][]} A list of candles ordered as timestamp, open, high, low,
   * close, volume
   */
  std::shared_future<std::any>
  fetchOHLCV(std::any symbol, std::any timeframe = std::string("1m"),
             std::any since = std::any{}, std::any limit = std::any{},
             std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{
                     {std::string("market"),
                      ::getValue(market, std::string("id"))},
                     {std::string("interval"),
                      this->safeString(this->timeframes, timeframe, timeframe)},
                 };
                 if (isTrue(!isEqual(since, std::any{}))) {
                   std::any maxLimit = 1440;
                   if (isTrue(isEqual(limit, std::any{}))) {
                     limit = maxLimit;
                   }
                   limit = mathMin(limit, maxLimit);
                   std::any start = this->parseToInt(divide(since, 1000));
                   ::setValue(request, std::string("start"), start);
                 }
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("limit"),
                              mathMin(limit, 1440));
                 }
                 std::any response = awaitValue(
                     this->v1PublicGetKline(this->extend(request, params)));
                 //
                 //     {
                 //         "success":true,
                 //         "message":"",
                 //         "result":[
                 //             [1591488000,"0.025025","0.025025","0.025029","0.025023","6.181","0.154686629"],
                 //             [1591488060,"0.025028","0.025033","0.025035","0.025026","8.067","0.201921167"],
                 //             [1591488120,"0.025034","0.02505","0.02505","0.025034","20.089","0.503114696"],
                 //         ]
                 //     }
                 //
                 std::any result = this->safeList(
                     response, std::string("result"), ccxt::list{});
                 return this->parseOHLCVs(result, market, timeframe, since,
                                          limit);
               })
        .share();
  }

  std::any parseOHLCV(std::any ohlcv, std::any market = std::any{}) override {
    //
    //     [
    //         1591488000,
    //         "0.025025",
    //         "0.025025",
    //         "0.025029",
    //         "0.025023",
    //         "6.181",
    //         "0.154686629"
    //     ]
    //
    return ccxt::list{
        this->safeTimestamp(ohlcv, 0), this->safeNumber(ohlcv, 1),
        this->safeNumber(ohlcv, 3),    this->safeNumber(ohlcv, 4),
        this->safeNumber(ohlcv, 2),    this->safeNumber(ohlcv, 5)};
  }

  /**
   * @method
   * @name whitebit#fetchStatus
   * @description the latest known information on the availability of the
   * exchange API
   * @see https://docs.whitebit.com/public/http-v4/#server-status
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [status structure]{@link
   * https://docs.ccxt.com/?id=exchange-status-structure}
   */
  std::shared_future<std::any>
  fetchStatus(std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        std::any response =
                            awaitValue(this->v4PublicGetPing(params));
                        //
                        //      [
                        //          "pong"
                        //      ]
                        //
                        std::any status = this->safeString(response, 0);
                        return ccxt::dict{
                            {std::string("status"),
                             (isTrue((isEqual(status, std::string("pong"))))
                                  ? std::any(std::string("ok"))
                                  : std::any(status))},
                            {std::string("updated"), std::any{}},
                            {std::string("eta"), std::any{}},
                            {std::string("url"), std::any{}},
                            {std::string("info"), response},
                        };
                      })
        .share();
  }

  /**
   * @method
   * @name whitebit#fetchTime
   * @description fetches the current integer timestamp in milliseconds from the
   * exchange server
   * @see https://docs.whitebit.com/public/http-v4/#server-time
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {int} the current integer timestamp in milliseconds from the
   * exchange server
   */
  std::shared_future<std::any>
  fetchTime(std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        std::any response =
                            awaitValue(this->v4PublicGetTime(params));
                        //
                        //     {
                        //         "time":1737380046
                        //     }
                        //
                        return this->safeIntegerProduct(
                            response, std::string("time"), 1000);
                      })
        .share();
  }

  /**
   * @method
   * @name whitebit#createMarketOrderWithCost
   * @description create a market order by providing the symbol, side and cost
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} side 'buy' or 'sell'
   * @param {float} cost how much you want to trade in units of the quote
   * currency
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  createMarketOrderWithCost(std::any symbol, std::any side, std::any cost,
                            std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        std::any req = ccxt::dict{
                            {std::string("cost"), cost},
                        };
                        // only buy side is supported
                        return awaitValue(this->createOrder(
                            symbol, std::string("market"), side, 0, std::any{},
                            this->extend(req, params)));
                      })
        .share();
  }

