  /**
   * @method
   * @name whitebit#fetchClosedOrders
   * @description fetches information on multiple closed orders made by the user
   * @see https://docs.whitebit.com/private/http-trade-v4/#query-executed-orders
   * @param {string} symbol unified market symbol of the market orders were made
   * in
   * @param {int} [since] the earliest time in ms to fetch orders for
   * @param {int} [limit] the maximum number of order structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  fetchClosedOrders(std::any symbol = std::any{}, std::any since = std::any{},
                    std::any limit = std::any{},
                    std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any request = ccxt::dict{};
                 std::any market = std::any{};
                 if (isTrue(!isEqual(symbol, std::any{}))) {
                   market = this->market(symbol);
                   symbol = ::getValue(market, std::string("symbol"));
                   ::setValue(request, std::string("market"),
                              ::getValue(market, std::string("id")));
                 }
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("limit"),
                              mathMin(limit, 100)); // default 50 max 100
                 }
                 std::any response =
                     awaitValue(this->v4PrivatePostTradeAccountOrderHistory(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "BTC_USDT": [
                 //             {
                 //                 "id": 160305483,
                 //                 "clientOrderId": "customId11",
                 //                 "time": 1594667731.724403,
                 //                 "side": "sell",
                 //                 "role": 2, // 1 = maker, 2 = taker
                 //                 "amount": "0.000076",
                 //                 "price": "9264.21",
                 //                 "deal": "0.70407996",
                 //                 "fee": "0.00070407996"
                 //             },
                 //         ],
                 //     }
                 //
                 std::any marketIds = getObjectKeys(response);
                 std::any results = ccxt::list{};
                 for (std::any i = 0; isLessThan(i, getArrayLength(marketIds));
                      postFixIncrement(i)) {
                   std::any marketId = ::getValue(marketIds, i);
                   std::any marketNew =
                       this->safeMarket(marketId, std::any{}, std::string("_"));
                   std::any orders =
                       this->safeList(response, marketId, ccxt::list{});
                   for (std::any j = 0; isLessThan(j, getArrayLength(orders));
                        postFixIncrement(j)) {
                     std::any order =
                         this->parseOrder(::getValue(orders, j), marketNew);
                     arrayPush(results,
                               this->extend(order, ccxt::dict{
                                                       {std::string("status"),
                                                        std::string("closed")},
                                                   }));
                   }
                 }
                 results = this->sortBy(results, std::string("timestamp"));
                 results = this->filterBySymbolSinceLimit(results, symbol,
                                                          since, limit);
                 return results;
               })
        .share();
  }

  virtual std::any parseOrderType(std::any type) {
    std::any types = ccxt::dict{
        {std::string("limit"), std::string("limit")},
        {std::string("market"), std::string("market")},
        {std::string("stop market"), std::string("market")},
        {std::string("stop limit"), std::string("limit")},
        {std::string("stock market"), std::string("market")},
        {std::string("margin limit"), std::string("limit")},
        {std::string("margin market"), std::string("market")},
    };
    return this->safeString(types, type, type);
  }

  std::any parseOrder(std::any order, std::any market = std::any{}) override {
    //
    // createOrder, fetchOpenOrders, cancelOrder
    //
    //      {
    //          "orderId":105687928629,
    //          "clientOrderId":"",
    //          "market":"DOGE_USDT",
    //          "side":"sell",
    //          "type":"stop market",
    //          "timestamp":1659091079.729576,
    //          "dealMoney":"0",                // executed amount in quote
    //          "dealStock":"0",                // base filled amount
    //          "amount":"100",
    //          "takerFee":"0.001",
    //          "makerFee":"0",
    //          "left":"100",
    //          "price": "40000", // price if price isset
    //          "dealFee":"0",
    //          "activation_price":"0.065"      // stop price (if stop limit or
    //          stop market)
    //      }
    //
    // fetchClosedOrders
    //
    //      {
    //          "id":105531094719,
    //          "clientOrderId":"",
    //          "ctime":1659045334.550127,
    //          "ftime":1659045334.550127,
    //          "side":"buy",
    //          "amount":"5.9940059",           // cost in terms of quote for
    //          regular market orders, amount in terms or base for all other
    //          order types "price":"0", "type":"market", "takerFee":"0.001",
    //          "makerFee":"0",
    //          "dealFee":"0.0059375815",
    //          "dealStock":"85",               // base filled amount
    //          "dealMoney":"5.9375815",        // executed amount in quote
    //      }
    //
    std::any marketId = this->safeString(order, std::string("market"));
    market = this->safeMarket(marketId, market, std::string("_"));
    std::any symbol = ::getValue(market, std::string("symbol"));
    std::any side = this->safeString(order, std::string("side"));
    std::any filled = this->safeString(order, std::string("dealStock"));
    std::any remaining = this->safeString(order, std::string("left"));
    std::any clientOrderId =
        this->safeString(order, std::string("clientOrderId"));
    if (isTrue(isEqual(clientOrderId, std::string("")))) {
      clientOrderId = std::any{};
    }
    std::any price = this->safeString(order, std::string("price"));
    std::any triggerPrice =
        this->safeNumber(order, std::string("activation_price"));
    std::any orderId =
        this->safeString2(order, std::string("orderId"), std::string("id"));
    std::any type = this->safeString(order, std::string("type"));
    std::any orderType = this->parseOrderType(type);
    if (isTrue(isEqual(orderType, std::string("market")))) {
      remaining = std::any{};
    }
    std::any amount = this->safeString(order, std::string("amount"));
    std::any cost = this->safeString(order, std::string("dealMoney"));
    if (isTrue(isTrue((isEqual(side, std::string("buy")))) &&
               isTrue((isTrue((isEqual(type, std::string("market")))) ||
                       isTrue((isEqual(type, std::string("stop market")))))))) {
      amount = filled;
    }
    std::any dealFee = this->safeString(order, std::string("dealFee"));
    std::any fee = std::any{};
    if (isTrue(!isEqual(dealFee, std::any{}))) {
      fee = ccxt::dict{
          {std::string("cost"), this->parseNumber(dealFee)},
          {std::string("currency"), ::getValue(market, std::string("quote"))},
      };
    }
    std::any timestamp = this->safeTimestamp2(order, std::string("ctime"),
                                              std::string("timestamp"));
    std::any lastTradeTimestamp =
        this->safeTimestamp(order, std::string("ftime"));
    std::any postOnly = this->safeBool(order, std::string("postOnly"));
    std::any ioc = this->safeBool(order, std::string("ioc"));
    std::any timeInForce = std::any{};
    if (isTrue(isEqual(ioc, true))) {
      timeInForce = std::string("IOC");
    } else if (isTrue(isEqual(postOnly, true))) {
      timeInForce = std::string("PO");
    }
    return this->safeOrder(
        ccxt::dict{
            {std::string("info"), order},
            {std::string("id"), orderId},
            {std::string("symbol"), symbol},
            {std::string("clientOrderId"), clientOrderId},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("lastTradeTimestamp"), lastTradeTimestamp},
            {std::string("timeInForce"), timeInForce},
            {std::string("postOnly"), postOnly},
            {std::string("status"), this->parseOrderStatus(this->safeString(
                                        order, std::string("status")))},
            {std::string("side"), side},
            {std::string("price"), price},
            {std::string("type"), orderType},
            {std::string("triggerPrice"), triggerPrice},
            {std::string("amount"), amount},
            {std::string("filled"), filled},
            {std::string("remaining"), remaining},
            {std::string("average"), std::any{}},
            {std::string("cost"), cost},
            {std::string("fee"), fee},
            {std::string("trades"), std::any{}},
        },
        market);
  }

  virtual std::any parseOrderStatus(std::any status) {
    std::any statuses = ccxt::dict{
        {std::string("CANCELED"), std::string("canceled")},
        {std::string("OPEN"), std::string("open")},
        {std::string("PARTIALLY_FILLED"), std::string("open")},
        {std::string("FILLED"), std::string("closed")},
    };
    return this->safeStringLower(statuses, status, status);
  }

  /**
   * @method
   * @name whitebit#fetchOrderTrades
   * @description fetch all the trades made from a single order
   * @see
   * https://docs.whitebit.com/private/http-trade-v4/#query-executed-order-deals
   * @param {string} id order id
   * @param {string} symbol unified market symbol
   * @param {int} [since] the earliest time in ms to fetch trades for
   * @param {int} [limit] the maximum number of trades to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=trade-structure}
   */
  std::shared_future<std::any>
  fetchOrderTrades(std::any id, std::any symbol = std::any{},
                   std::any since = std::any{}, std::any limit = std::any{},
                   std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any request = ccxt::dict{
                            {std::string("orderId"), parseInt(id)},
                        };
                        std::any market = std::any{};
                        if (isTrue(!isEqual(symbol, std::any{}))) {
                          market = this->market(symbol);
                          ::setValue(request, std::string("market"),
                                     ::getValue(market, std::string("id")));
                        }
                        if (isTrue(!isEqual(limit, std::any{}))) {
                          ::setValue(request, std::string("limit"),
                                     mathMin(limit, 100));
                        }
                        std::any response =
                            awaitValue(this->v4PrivatePostTradeAccountOrder(
                                this->extend(request, params)));
                        //
                        //     {
                        //         "records": [
                        //             {
                        //                 "time": 1593342324.613711,
                        //                 "fee": "0.00000419198",
                        //                 "price": "0.00000701",
                        //                 "amount": "598",
                        //                 "id": 149156519, // trade id
                        //                 "dealOrderId": 3134995325, // orderId
                        //                 "clientOrderId": "customId11", //
                        //                 empty string if not specified "role":
                        //                 2, // 1 = maker, 2 = taker "deal":
                        //                 "0.00419198"
                        //             }
                        //         ],
                        //         "offset": 0,
                        //         "limit": 100
                        //     }
                        //
                        std::any data = this->safeList(
                            response, std::string("records"), ccxt::list{});
                        return this->parseTrades(data, market);
                      })
        .share();
  }

  /**
   * @method
   * @name whitebit#fetchWithdrawals
   * @description fetch all withdrawals made from an account
   * @see
   * https://docs.whitebit.com/private/http-main-v4/#get-depositwithdraw-history
   * @param {string} code unified currency code
   * @param {int} [since] the earliest time in ms to fetch withdrawals for
   * @param {int} [limit] the maximum number of withdrawals structures to
   * retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.transactionMethod] transaction method (1=deposit,
   * 2=withdrawal) - automatically set to '2' for withdrawals
   * @returns {object[]} a list of [transaction structures]{@link
   * https://docs.ccxt.com/?id=transaction-structure}
   */
  std::shared_future<std::any>
  fetchWithdrawals(std::any code = std::any{}, std::any since = std::any{},
                   std::any limit = std::any{},
                   std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any currency = std::any{};
                        std::any request = ccxt::dict{};
                        if (isTrue(!isEqual(code, std::any{}))) {
                          currency = this->currency(code);
                          ::setValue(request, std::string("ticker"),
                                     ::getValue(currency, std::string("id")));
                        }
                        if (isTrue(!isEqual(since, std::any{}))) {
                          ::setValue(request, std::string("startDate"),
                                     this->parseToInt(divide(since, 1000)));
                        }
                        if (isTrue(isTrue(isEqual(limit, std::any{})) ||
                                   isTrue(isGreaterThan(limit, 100)))) {
                          limit = 100;
                        }
                        if (isTrue(!isEqual(limit, std::any{}))) {
                          ::setValue(request, std::string("limit"), limit);
                        }
                        // Use transactionMethod parameter to filter withdrawals
                        // server-side (method = 2)
                        ::setValue(request, std::string("transactionMethod"),
                                   std::string("2"));
                        std::any response =
                            awaitValue(this->v4PrivatePostMainAccountHistory(
                                this->extend(request, params)));
                        //
                        //     [
                        //         {
                        //             "id": 123456789,                    //
                        //             Transaction ID "method": "2", // Method:
                        //             1=deposit, 2=withdrawal (filtered
                        //             server-side) "ticker": "BTC", // Currency
                        //             ticker "amount": "0.001", // Transaction
                        //             amount "address":
                        //             "1A1zP1eP5QGefi2DMPTfTL5SLmv7DivfNa", //
                        //             Withdrawal address "memo": "", //
                        //             Memo/tag (if required) "network": "BTC",
                        //             // Network name "fee": "0.0005", //
                        //             Transaction fee "status": "1", // Status:
                        //             0=pending, 1=completed, 2=failed
                        //             "timestamp": 1641051917,            //
                        //             Transaction timestamp "txid":
                        //             "abc123def456..."           //
                        //             Transaction hash
                        //         },
                        //         { ... }                                 //
                        //         More withdrawal transactions
                        //     ]
                        //
                        return this->parseTransactions(
                            this->safeList(response, std::string("records"),
                                           ccxt::list{}),
                            currency, since, limit);
                      })
        .share();
  }

  /**
   * @method
   * @name whitebit#fetchTransactions
   * @description fetch history of deposits and withdrawals
   * @see
   * https://docs.whitebit.com/private/http-main-v4/#get-depositwithdraw-history
   * @param {string} [code] unified currency code
   * @param {int} [since] the earliest time in ms to fetch transactions for
   * @param {int} [limit] the maximum number of transactions structures to
   * retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.transactionMethod] transaction method (1=deposit,
   * 2=withdrawal) - automatically set to '1' for deposits
   * @returns {object[]} a list of [transaction structures]{@link
   * https://docs.ccxt.com/?id=transaction-structure}
   */
  std::shared_future<std::any>
  fetchTransactions(std::any code = std::any{}, std::any since = std::any{},
                    std::any limit = std::any{},
                    std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any currency = std::any{};
                        std::any request = ccxt::dict{};
                        if (isTrue(!isEqual(code, std::any{}))) {
                          currency = this->currency(code);
                          ::setValue(request, std::string("ticker"),
                                     ::getValue(currency, std::string("id")));
                        }
                        if (isTrue(!isEqual(since, std::any{}))) {
                          ::setValue(request, std::string("startDate"),
                                     this->parseToInt(divide(since, 1000)));
                        }
                        if (isTrue(isTrue(isEqual(limit, std::any{})) ||
                                   isTrue(isGreaterThan(limit, 100)))) {
                          limit = 100;
                        }
                        if (isTrue(!isEqual(limit, std::any{}))) {
                          ::setValue(request, std::string("limit"), limit);
                        }
                        // Do not filter by transactionMethod to get all
                        // transactions (deposits and withdrawals)
                        std::any response =
                            awaitValue(this->v4PrivatePostMainAccountHistory(
                                this->extend(request, params)));
                        //
                        //     {
                        //         "records": [
                        //             {
                        //                 "address":
                        //                 "TDepositAddressExample1111111111111",
                        //                 "uniqueId": null,
                        //                 "transactionId":
                        //                 "11111111-2222-3333-4444-555555555555",
                        //                 "createdAt": 1786182572,
                        //                 "currency": "Tether US",
                        //                 "ticker": "USDT",
                        //                 "method": 1,                    // 1
                        //                 = deposit, 2 = withdraw "amount":
                        //                 "20.723117", "description": null,
                        //                 "memo": null,
                        //                 "fee": "0",
                        //                 "status": 3,
                        //                 "network": "TRC20",
                        //                 "transactionHash":
                        //                 "a1b2c3d4e5f6a7b8c9d0e1f2a3b4c5d6e7f8a9b0c1d2e3f4a5b6c7d8e9f0a1b2",
                        //                 "details": { "partial": null },
                        //                 "centralized": false
                        //             }
                        //         ],
                        //         "total": 1,
                        //         "limit": 100,
                        //         "offset": 0
                        //     }
                        //
                        std::any records = this->safeList(
                            response, std::string("records"), ccxt::list{});
                        return this->parseTransactions(records, currency, since,
                                                       limit);
                      })
        .share();
  }

  /**
   * @method
   * @name whitebit#fetchDepositAddress
   * @description fetch the deposit address for a currency associated with this
   * account
   * @see
   * https://docs.whitebit.com/private/http-main-v4/#get-fiat-deposit-address
   * @see
   * https://docs.whitebit.com/private/http-main-v4/#get-cryptocurrency-deposit-address
   * @param {string} code unified currency code
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [address structure]{@link
   * https://docs.ccxt.com/?id=address-structure}
   */
  std::shared_future<std::any>
  fetchDepositAddress(std::any code, std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any currency = this->currency(code);
                 std::any request = ccxt::dict{
                     {std::string("ticker"),
                      ::getValue(currency, std::string("id"))},
                 };
                 std::any response = std::any{};
                 if (isTrue(this->isFiat(code))) {
                   std::any provider =
                       this->safeString(params, std::string("provider"));
                   if (isTrue(isEqual(provider, std::any{}))) {
                     throw ArgumentsRequired(toString(
                         add(this->id,
                             std::string(" fetchDepositAddress() requires a "
                                         "provider when the ticker is fiat"))));
                   }
                   ::setValue(request, std::string("provider"), provider);
                   std::any amount =
                       this->safeNumber(params, std::string("amount"));
                   if (isTrue(isEqual(amount, std::any{}))) {
                     throw ArgumentsRequired(toString(
                         add(this->id,
                             std::string(" fetchDepositAddress() requires an "
                                         "amount when the ticker is fiat"))));
                   }
                   ::setValue(request, std::string("amount"), amount);
                   std::any uniqueId =
                       this->safeValue(params, std::string("uniqueId"));
                   if (isTrue(isEqual(uniqueId, std::any{}))) {
                     throw ArgumentsRequired(toString(
                         add(this->id,
                             std::string(" fetchDepositAddress() requires an "
                                         "uniqueId when the ticker is fiat"))));
                   }
                   response =
                       awaitValue(this->v4PrivatePostMainAccountFiatDepositUrl(
                           this->extend(request, params)));
                 } else {
                   response = awaitValue(this->v4PrivatePostMainAccountAddress(
                       this->extend(request, params)));
                 }
                 //
                 // fiat
                 //
                 //     {
                 //         "url": "https://someaddress.com"
                 //     }
                 //
                 // crypto
                 //
                 //     {
                 //         "account": {
                 //             "address":
                 //             "GDTSOI56XNVAKJNJBLJGRNZIVOCIZJRBIDKTWSCYEYNFAZEMBLN75RMN",
                 //             "memo": "48565488244493"
                 //         },
                 //         "required": {
                 //             "fixedFee": "0",
                 //             "flexFee": {
                 //                 "maxFee": "0",
                 //                 "minFee": "0",
                 //                 "percent": "0"
                 //             },
                 //             "maxAmount": "0",
                 //             "minAmount": "1"
                 //         }
                 //     }
                 //
                 std::any url = this->safeString(response, std::string("url"));
                 std::any account = this->safeValue(
                     response, std::string("account"), ccxt::dict{});
                 std::any address =
                     this->safeString(account, std::string("address"), url);
                 std::any tag = this->safeString(account, std::string("memo"));
                 this->checkAddress(address);
                 return ccxt::dict{
                     {std::string("info"), response},
                     {std::string("currency"), code},
                     {std::string("network"), std::any{}},
                     {std::string("address"), address},
                     {std::string("tag"), tag},
                 };
               })
        .share();
  }

  /**
   * @method
   * @name whitebit#createDepositAddress
   * @description create a currency deposit address
   * @see
   * https://docs.whitebit.com/private/http-main-v4/#create-new-address-for-deposit
   * @param {string} code unified currency code of the currency for the deposit
   * address
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.network] the blockchain network to create a deposit
   * address on
   * @param {string} [params.type] address type, available for specific
   * currencies
   * @returns {object} an [address structure]{@link
   * https://docs.ccxt.com/?id=address-structure}
   */
  std::shared_future<std::any>
  createDepositAddress(std::any code, std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any currency = this->currency(code);
                        std::any request = ccxt::dict{
                            {std::string("ticker"),
                             ::getValue(currency, std::string("id"))},
                        };
                        std::any response = awaitValue(
                            this->v4PrivatePostMainAccountCreateNewAddress(
                                this->extend(request, params)));
                        //
                        //     {
                        //         "account": {
                        //             "address":
                        //             "GDTSOI56XNVAKJNJBLJGRNZIVOCIZJRBIDKTWSCYEYNFAZEMBLN75RMN",
                        //             "memo": "48565488244493"
                        //         },
                        //         "required": {
                        //             "maxAmount": "0",
                        //             "minAmount": "1",
                        //             "fixedFee": "0",
                        //             "flexFee": {
                        //                 "maxFee": "0",
                        //                 "minFee": "0",
                        //                 "percent": "0"
                        //             }
                        //         }
                        //     }
                        //
                        std::any data = this->safeDict(
                            response, std::string("account"), ccxt::dict{});
                        return this->parseDepositAddress(data, currency);
                      })
        .share();
  }

  std::any parseDepositAddress(std::any depositAddress,
                               std::any currency = std::any{}) override {
    //
    //     {
    //         "address":
    //         "GDTSOI56XNVAKJNJBLJGRNZIVOCIZJRBIDKTWSCYEYNFAZEMBLN75RMN",
    //         "memo": "48565488244493"
    //     },
    //
    return ccxt::dict{
        {std::string("info"), depositAddress},
        {std::string("currency"), this->safeCurrencyCode(std::any{}, currency)},
        {std::string("network"), std::any{}},
        {std::string("address"),
         this->safeString(depositAddress, std::string("address"))},
        {std::string("tag"),
         this->safeString(depositAddress, std::string("memo"))},
    };
  }

  /**
   * @method
   * @name whitebit#fetchAccounts
   * @description fetch all the accounts associated with a profile
   * @see https://docs.whitebit.com/private/http-main-v4/#sub-account-list
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} a list of [account structures]{@link
   * https://docs.ccxt.com/?id=account-structure}
   */
  std::shared_future<std::any>
  fetchAccounts(std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any accounts = ccxt::list{};
                 std::any response =
                     awaitValue(this->v4PrivatePostSubAccountList(params));
                 //
                 //     {
                 //         "offset": 0,
                 //         "limit": 100,
                 //         "data": [
                 //             {
                 //                 "id":
                 //                 "8e667b4a-0b71-4988-8af5-9474dbfaeb51",
                 //                 "alias": "trading_bot",
                 //                 "userId": "u-12345",
                 //                 "email": "s***@example.com",
                 //                 "status": "active",
                 //                 "color": "#FF5733",
                 //                 "kyc": { "shareKyc": false, "kycStatus":
                 //                 "verified" }, "permissions": {
                 //                 "spotEnabled": true, "collateralEnabled":
                 //                 false }
                 //             }
                 //         ]
                 //     }
                 //
                 std::any subAccounts = this->safeList(
                     response, std::string("data"), ccxt::list{});
                 for (std::any i = 0;
                      isLessThan(i, getArrayLength(subAccounts));
                      postFixIncrement(i)) {
                   std::any subAccount =
                       this->safeDict(subAccounts, i, ccxt::dict{});
                   std::any accountId =
                       this->safeString(subAccount, std::string("id"));
                   std::any accountName =
                       this->safeString(subAccount, std::string("alias"));
                   arrayPush(accounts, ccxt::dict{
                                           {std::string("id"), accountId},
                                           {std::string("type"),
                                            std::string("subaccount")},
                                           {std::string("name"), accountName},
                                           {std::string("code"), std::any{}},
                                           {std::string("info"), subAccount},
                                       });
                 }
                 return accounts;
               })
        .share();
  }

  /**
   * @method
   * @name whitebit#setLeverage
   * @description set the level of leverage for a market
   * @see
   * https://docs.whitebit.com/private/http-trade-v4/#change-collateral-account-leverage
   * @param {float} leverage the rate of leverage
   * @param {string} symbol unified market symbol
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} response from the exchange
   */
  std::shared_future<std::any>
  setLeverage(std::any leverage, std::any symbol = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::
        async(std::launch::deferred,
              [=]() mutable -> std::any {
                if (isTrue(isEqual(this->markets, std::any{}))) {
                  awaitValue(this->loadMarkets());
                }
                if (isTrue(!isEqual(symbol, std::any{}))) {
                  throw NotSupported(toString(add(
                      this->id,
                      std::string(
                          " setLeverage() does not allow to set per symbol"))));
                }
                if (isTrue(isTrue((isLessThan(leverage, 1))) ||
                           isTrue((isGreaterThan(leverage, 20))))) {
                  throw BadRequest(toString(add(
                      this->id, std::string(" setLeverage() leverage should be "
                                            "between 1 and 20"))));
                }
                std::any request = ccxt::dict{
                    {std::string("leverage"), leverage},
                };
                return awaitValue(this->v4PrivatePostCollateralAccountLeverage(
                    this->extend(request, params)));
              })
            .share();
  }

  /**
   * @method
   * @name whitebit#transfer
   * @description transfer currency internally between wallets on the same
   * account
   * @see
   * https://docs.whitebit.com/private/http-main-v4/#transfer-between-main-and-trade-balances
   * @param {string} code unified currency code
   * @param {float} amount amount to transfer
   * @param {string} fromAccount account to transfer from - main, spot,
   * collateral
   * @param {string} toAccount account to transfer to - main, spot, collateral
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [transfer structure]{@link
   * https://docs.ccxt.com/?id=transfer-structure}
   */
  std::shared_future<std::any>
  transfer(std::any code, std::any amount, std::any fromAccount,
           std::any toAccount, std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any currency = this->currency(code);
                        std::any accountsByType = this->safeValue(
                            this->options, std::string("accountsByType"));
                        std::any fromAccountId = this->safeString(
                            accountsByType, fromAccount, fromAccount);
                        std::any toAccountId = this->safeString(
                            accountsByType, toAccount, toAccount);
                        std::any amountString =
                            this->currencyToPrecision(code, amount);
                        std::any request = ccxt::dict{
                            {std::string("ticker"),
                             ::getValue(currency, std::string("id"))},
                            {std::string("amount"), amountString},
                            {std::string("from"), fromAccountId},
                            {std::string("to"), toAccountId},
                        };
                        std::any response =
                            awaitValue(this->v4PrivatePostMainAccountTransfer(
                                this->extend(request, params)));
                        //
                        //    []
                        //
                        return this->parseTransfer(response, currency);
                      })
        .share();
  }

  std::any parseTransfer(std::any transfer,
                         std::any currency = std::any{}) override {
    //
    //    []
    //
    return ccxt::dict{
        {std::string("info"), transfer},
        {std::string("id"), std::any{}},
        {std::string("timestamp"), std::any{}},
        {std::string("datetime"), std::any{}},
        {std::string("currency"), this->safeCurrencyCode(std::any{}, currency)},
        {std::string("amount"), std::any{}},
        {std::string("fromAccount"), std::any{}},
        {std::string("toAccount"), std::any{}},
        {std::string("status"), std::any{}},
    };
  }

  /**
   * @method
   * @name whitebit#withdraw
   * @description make a withdrawal
   * @see
   * https://docs.whitebit.com/private/http-main-v4/#create-withdraw-request
   * @param {string} code unified currency code
   * @param {float} amount the amount to withdraw
   * @param {string} address the address to withdraw to
   * @param {string} tag
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [transaction structure]{@link
   * https://docs.ccxt.com/?id=transaction-structure}
   */
  std::shared_future<std::any>
  withdraw(std::any code, std::any amount, std::any address,
           std::any tag = std::any{}, std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any currency =
                     this->currency(code); // check if it has canDeposit
                 std::any request = ccxt::dict{
                     {std::string("ticker"),
                      ::getValue(currency, std::string("id"))},
                     {std::string("amount"),
                      this->currencyToPrecision(code, amount)},
                     {std::string("address"), address},
                 };
                 std::any uniqueId =
                     this->safeValue(params, std::string("uniqueId"));
                 if (isTrue(isEqual(uniqueId, std::any{}))) {
                   uniqueId = this->uuid22();
                 }
                 ::setValue(request, std::string("uniqueId"), uniqueId);
                 if (isTrue(!isEqual(tag, std::any{}))) {
                   ::setValue(request, std::string("memo"), tag);
                 }
                 if (isTrue(this->isFiat(code))) {
                   std::any provider =
                       this->safeValue(params, std::string("provider"));
                   if (isTrue(isEqual(provider, std::any{}))) {
                     throw ArgumentsRequired(toString(
                         add(this->id,
                             std::string(" withdraw() requires a provider when "
                                         "the ticker is fiat"))));
                   }
                   ::setValue(request, std::string("provider"), provider);
                 }
                 std::any response =
                     awaitValue(this->v4PrivatePostMainAccountWithdraw(
                         this->extend(request, params)));
                 //
                 // empty array with a success status
                 // go to deposit/withdraw history and check you request status
                 // by uniqueId
                 //
                 //     []
                 //
                 return this->extend(this->parseTransaction(response, currency),
                                     ccxt::dict{
                                         {std::string("id"), uniqueId},
                                     });
               })
        .share();
  }

  std::any parseTransaction(std::any transaction,
                            std::any currency = std::any{},
                            std::any p2 = std::any{},
                            std::any p3 = std::any{}) override {
    //
    //     {
    //         "address": "3ApEASLcrQtZpg1TsssFgYF5V5YQJAKvuE", // deposit
    //         address "uniqueId": null, // unique Id of deposit
    //         "transactionId": "a6d71d69-2b17-4ad8-8b15-2d686c54a1a5",
    //         "createdAt": 1593437922, // timestamp of deposit "currency":
    //         "Bitcoin", // deposit currency "ticker": "BTC", // deposit
    //         currency ticker "method": 1, // called method 1 - deposit, 2 -
    //         withdraw "amount": "0.0006", // amount of deposit "description":
    //         "", // deposit description "memo": "", // deposit memo "fee":
    //         "0", // deposit fee "status": 15, // transactions status
    //         "network": null, // if currency is multinetwork
    //         "transactionHash":
    //         "a275a514013e4e0f927fd0d1bed215e7f6f2c4c6ce762836fe135ec22529d886",
    //         // deposit transaction hash "details": {
    //             "partial": { // details about partially successful
    //             withdrawals
    //                 "requestAmount": "50000", // requested withdrawal amount
    //                 "processedAmount": "39000", // processed withdrawal
    //                 amount "processedFee": "273", // fee for processed
    //                 withdrawal amount "normalizeTransaction": "" // deposit
    //                 id
    //             }
    //         },
    //         "confirmations": { // if transaction status == 15 you can see
    //         this object
    //             "actual": 1, // current block confirmations "required": 2 //
    //             required block confirmation for successful deposit
    //         }
    //         "centralized": false,
    //     }
    //
    currency = this->safeCurrency(std::any{}, currency);
    std::any address = this->safeString(transaction, std::string("address"));
    std::any timestamp =
        this->safeTimestamp(transaction, std::string("createdAt"));
    std::any currencyId = this->safeString(transaction, std::string("ticker"));
    std::any status = this->safeString(transaction, std::string("status"));
    std::any method = this->safeString(transaction, std::string("method"));
    return ccxt::dict{
        {std::string("id"),
         this->safeString(transaction, std::string("uniqueId"))},
        {std::string("txid"),
         this->safeString(transaction, std::string("transactionId"))},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
        {std::string("network"),
         this->safeString(transaction, std::string("network"))},
        {std::string("addressFrom"),
         (isTrue((isEqual(method, std::string("1")))) ? std::any(address)
                                                      : std::any(std::any{}))},
        {std::string("address"), address},
        {std::string("addressTo"),
         (isTrue((isEqual(method, std::string("2")))) ? std::any(address)
                                                      : std::any(std::any{}))},
        {std::string("amount"),
         this->safeNumber(transaction, std::string("amount"))},
        {std::string("type"), (isTrue((isEqual(method, std::string("1"))))
                                   ? std::any(std::string("deposit"))
                                   : std::any(std::string("withdrawal")))},
        {std::string("currency"), this->safeCurrencyCode(currencyId, currency)},
        {std::string("status"), this->parseTransactionStatus(status)},
        {std::string("updated"), std::any{}},
        {std::string("tagFrom"), std::any{}},
        {std::string("tag"),
         this->safeString(transaction, std::string("memo"))},
        {std::string("tagTo"), std::any{}},
        {std::string("comment"),
         this->safeString(transaction, std::string("description"))},
        {std::string("internal"), std::any{}},
        {std::string("fee"),
         ccxt::dict{
             {std::string("cost"),
              this->safeNumber(transaction, std::string("fee"))},
             {std::string("currency"),
              this->safeCurrencyCode(currencyId, currency)},
         }},
        {std::string("info"), transaction},
    };
  }

  virtual std::any parseTransactionStatus(std::any status) {
    std::any statuses = ccxt::dict{
        {std::string("1"), std::string("pending")},
        {std::string("2"), std::string("pending")},
        {std::string("3"), std::string("ok")},
        {std::string("4"), std::string("canceled")},
        {std::string("5"), std::string("pending")},
        {std::string("6"), std::string("pending")},
        {std::string("7"), std::string("ok")},
        {std::string("9"), std::string("canceled")},
        {std::string("10"), std::string("pending")},
        {std::string("11"), std::string("pending")},
        {std::string("12"), std::string("pending")},
        {std::string("13"), std::string("pending")},
        {std::string("14"), std::string("pending")},
        {std::string("15"), std::string("pending")},
        {std::string("16"), std::string("pending")},
        {std::string("17"), std::string("pending")},
    };
    return this->safeString(statuses, status, status);
  }

  /**
   * @method
   * @name whitebit#fetchDeposit
   * @description fetch information on a deposit
   * @see
   * https://docs.whitebit.com/private/http-main-v4/#get-depositwithdraw-history
   * @param {string} id deposit id
   * @param {string} code not used by fetchDeposit ()
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [transaction structure]{@link
   * https://docs.ccxt.com/?id=transaction-structure}
   */
  virtual std::shared_future<std::any>
  fetchDeposit(std::any id, std::any code = std::any{},
               std::any params = ccxt::dict{}) {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any currency = std::any{};
                        std::any request = ccxt::dict{
                            {std::string("transactionMethod"), 1},
                            {std::string("uniqueId"), id},
                            {std::string("limit"), 1},
                            {std::string("offset"), 0},
                        };
                        if (isTrue(!isEqual(code, std::any{}))) {
                          currency = this->currency(code);
                          ::setValue(request, std::string("ticker"),
                                     ::getValue(currency, std::string("id")));
                        }
                        std::any response =
                            awaitValue(this->v4PrivatePostMainAccountHistory(
                                this->extend(request, params)));
                        //
                        //     {
                        //         "limit": 100,
                        //         "offset": 0,
                        //         "records": [
                        //             {
                        //                 "address":
                        //                 "3ApEASLcrQtZpg1TsssFgYF5V5YQJAKvuE",
                        //                 // deposit address "uniqueId": null,
                        //                 // unique Id of deposit "createdAt":
                        //                 1593437922, // timestamp of deposit
                        //                 "currency": "Bitcoin", // deposit
                        //                 currency "ticker": "BTC", // deposit
                        //                 currency ticker "method": 1, //
                        //                 called method 1 - deposit, 2 -
                        //                 withdraw "amount": "0.0006", //
                        //                 amount of deposit "description": "",
                        //                 // deposit description "memo": "", //
                        //                 deposit memo "fee": "0", // deposit
                        //                 fee "status": 15, // transactions
                        //                 status "network": null, // if
                        //                 currency is multinetwork
                        //                 "transactionHash":
                        //                 "a275a514013e4e0f927fd0d1bed215e7f6f2c4c6ce762836fe135ec22529d886",
                        //                 // deposit transaction hash
                        //                 "details": {
                        //                     "partial": { // details about
                        //                     partially successful withdrawals
                        //                         "requestAmount": "50000", //
                        //                         requested withdrawal amount
                        //                         "processedAmount": "39000",
                        //                         // processed withdrawal
                        //                         amount "processedFee": "273",
                        //                         // fee for processed
                        //                         withdrawal amount
                        //                         "normalizeTransaction": "" //
                        //                         deposit id
                        //                     }
                        //                 },
                        //                 "confirmations": { // if transaction
                        //                 status == 15 you can see this object
                        //                     "actual": 1, // current block
                        //                     confirmations "required": 2 //
                        //                     required block confirmation for
                        //                     successful deposit
                        //                 }
                        //             },
                        //             {...},
                        //         ],
                        //         "total": 300 // total number of transactions,
                        //         use this for calculating ‘limit’ and ‘offset'
                        //     }
                        //
                        std::any records = this->safeValue(
                            response, std::string("records"), ccxt::list{});
                        std::any first =
                            this->safeDict(records, 0, ccxt::dict{});
                        return this->parseTransaction(first, currency);
                      })
        .share();
  }

  /**
   * @method
   * @name whitebit#fetchDeposits
   * @description fetch all deposits made to an account
   * @see
   * https://docs.whitebit.com/private/http-main-v4/#get-depositwithdraw-history
   * @param {string} code unified currency code
   * @param {int} [since] the earliest time in ms to fetch deposits for
   * @param {int} [limit] the maximum number of deposits structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} a list of [transaction structures]{@link
   * https://docs.ccxt.com/?id=transaction-structure}
   */
  std::shared_future<std::any>
  fetchDeposits(std::any code = std::any{}, std::any since = std::any{},
                std::any limit = std::any{},
                std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any currency = std::any{};
                        std::any request = ccxt::dict{
                            {std::string("transactionMethod"), 1},
                            {std::string("limit"), 100},
                            {std::string("offset"), 0},
                        };
                        if (isTrue(!isEqual(code, std::any{}))) {
                          currency = this->currency(code);
                          ::setValue(request, std::string("ticker"),
                                     ::getValue(currency, std::string("id")));
                        }
                        if (isTrue(!isEqual(limit, std::any{}))) {
                          ::setValue(request, std::string("limit"),
                                     mathMin(limit, 100));
                        }
                        std::any response =
                            awaitValue(this->v4PrivatePostMainAccountHistory(
                                this->extend(request, params)));
                        //
                        //     {
                        //         "limit": 100,
                        //         "offset": 0,
                        //         "records": [
                        //             {
                        //                 "address":
                        //                 "3ApEASLcrQtZpg1TsssFgYF5V5YQJAKvuE",
                        //                 // deposit address "uniqueId": null,
                        //                 // unique Id of deposit "createdAt":
                        //                 1593437922, // timestamp of deposit
                        //                 "currency": "Bitcoin", // deposit
                        //                 currency "ticker": "BTC", // deposit
                        //                 currency ticker "method": 1, //
                        //                 called method 1 - deposit, 2 -
                        //                 withdraw "amount": "0.0006", //
                        //                 amount of deposit "description": "",
                        //                 // deposit description "memo": "", //
                        //                 deposit memo "fee": "0", // deposit
                        //                 fee "status": 15, // transactions
                        //                 status "network": null, // if
                        //                 currency is multinetwork
                        //                 "transactionHash":
                        //                 "a275a514013e4e0f927fd0d1bed215e7f6f2c4c6ce762836fe135ec22529d886",
                        //                 // deposit transaction hash
                        //                 "details": {
                        //                     "partial": { // details about
                        //                     partially successful withdrawals
                        //                         "requestAmount": "50000", //
                        //                         requested withdrawal amount
                        //                         "processedAmount": "39000",
                        //                         // processed withdrawal
                        //                         amount "processedFee": "273",
                        //                         // fee for processed
                        //                         withdrawal amount
                        //                         "normalizeTransaction": "" //
                        //                         deposit id
                        //                     }
                        //                 },
                        //                 "confirmations": { // if transaction
                        //                 status == 15 you can see this object
                        //                     "actual": 1, // current block
                        //                     confirmations "required": 2 //
                        //                     required block confirmation for
                        //                     successful deposit
                        //                 }
                        //             },
                        //             {...},
                        //         ],
                        //         "total": 300 // total number of transactions,
                        //         use this for calculating ‘limit’ and ‘offset'
                        //     }
                        //
                        std::any records = this->safeList(
                            response, std::string("records"), ccxt::list{});
                        std::any recordsList = ccxt::list{};
                        if (isTrue(!isEqual(records, std::any{}))) {
                          recordsList = records;
                        }
                        return this->parseTransactions(recordsList, currency,
                                                       since, limit);
                      })
        .share();
  }

  /**
   * @method
   * @name whitebit#fetchBorrowInterest
   * @description fetch the interest owed by the user for borrowing currency for
   * margin trading
   * @see https://docs.whitebit.com/private/http-trade-v4/#open-positions
   * @param {string} code unified currency code
   * @param {string} symbol unified market symbol
   * @param {int} [since] the earliest time in ms to fetch borrrow interest for
   * @param {int} [limit] the maximum number of structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} a list of [borrow interest structures]{@link
   * https://docs.ccxt.com/?id=borrow-interest-structure}
   */
  std::shared_future<std::any>
  fetchBorrowInterest(std::any code = std::any{}, std::any symbol = std::any{},
                      std::any since = std::any{}, std::any limit = std::any{},
                      std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any request = ccxt::dict{};
                        std::any market = std::any{};
                        if (isTrue(!isEqual(symbol, std::any{}))) {
                          market = this->market(symbol);
                          ::setValue(request, std::string("market"),
                                     ::getValue(market, std::string("id")));
                        }
                        std::any response = awaitValue(
                            this->v4PrivatePostCollateralAccountPositionsOpen(
                                this->extend(request, params)));
                        //
                        //     [
                        //         {
                        //             "positionId": 191823,
                        //             "market": "BTC_USDT",
                        //             "openDate": 1660340344.027163,
                        //             "modifyDate": 1660340344.027163,
                        //             "amount": "0.003075",
                        //             "basePrice": "24149.24512",
                        //             "liquidationPrice": "7059.02",
                        //             "leverage": "5",
                        //             "pnl": "-0.15",
                        //             "pnlPercent": "-0.20",
                        //             "margin": "14.86",
                        //             "freeMargin": "44.99",
                        //             "funding": "0",
                        //             "unrealizedFunding":
                        //             "0.0000307828284903", "liquidationState":
                        //             null
                        //         }
                        //     ]
                        //
                        std::any interest =
                            this->parseBorrowInterests(response, market);
                        return this->filterByCurrencySinceLimit(interest, code,
                                                                since, limit);
                      })
        .share();
  }

  std::any parseBorrowInterest(std::any info,
                               std::any market = std::any{}) override {
    //
    //     {
    //         "positionId": 191823,
    //         "market": "BTC_USDT",
    //         "openDate": 1660340344.027163,
    //         "modifyDate": 1660340344.027163,
    //         "amount": "0.003075",
    //         "basePrice": "24149.24512",
    //         "liquidationPrice": "7059.02",
    //         "leverage": "5",
    //         "pnl": "-0.15",
    //         "pnlPercent": "-0.20",
    //         "margin": "14.86",
    //         "freeMargin": "44.99",
    //         "funding": "0",
    //         "unrealizedFunding": "0.0000307828284903",
    //         "liquidationState": null
    //     }
    //
    std::any marketId = this->safeString(info, std::string("market"));
    std::any symbol = this->safeSymbol(marketId, market, std::string("_"));
    std::any timestamp = this->safeTimestamp(info, std::string("modifyDate"));
    return ccxt::dict{
        {std::string("info"), info},
        {std::string("symbol"), symbol},
        {std::string("currency"), std::string("USDT")},
        {std::string("interest"),
         this->safeNumber(info, std::string("unrealizedFunding"))},
        {std::string("interestRate"), 0.00098},
        {std::string("amountBorrowed"),
         this->safeNumber(info, std::string("amount"))},
        {std::string("marginMode"), std::string("cross")},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
    };
  }

